span["parent"] = current
span["duration_ms"] = round((time.perf_counter() - span["started_at"]) * 1000, 2)
# 树形渲染:递归降深度,前导空格即层级
def show(spans, indent=""):
    for s in spans:
        print(f"{indent}{s['name']} {s.get('duration_ms', 0)}ms")
        show(s["children"], indent + "  ")

